import{_ as a,a0 as s,w as l,s as d,ao as i,I as r,x as t,a1 as p,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"安裝完最小化 RHEL/CentOS 7 後需要做的 30 件事情（四） | LCTT x X-CMD","titleTemplate":false,"description":"安裝完最小化 RHEL/CentOS 7 後需要做的 30 件事情（四） | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安裝完最小化 RHEL/CentOS 7 後需要做的 30 件事情（四） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安裝完最小化 RHEL/CentOS 7 後需要做的 30 件事情（四） | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/30 Things to Do After Minimal RHEL or CentOS 7 Installation--4","title":"安裝完最小化 RHEL/CentOS 7 後需要做的 30 件事情（四）","tag":"201505","desc":""},"relativePath":"201505/30 Things to Do After Minimal RHEL or CentOS 7 Installation--4.md","filePath":"[post].md"}'),m={name:"201505/30 Things to Do After Minimal RHEL or CentOS 7 Installation--4.md"};function c(u,e,h,w,f,L){const n=s("Link");return l(),d("div",null,[e[16]||(e[16]=i(`<h1 id="安裝完最小化-rhel-centos-7-後需要做的-30-件事情-四" tabindex="-1">安裝完最小化 RHEL/CentOS 7 後需要做的 30 件事情（四） <a class="header-anchor" href="#安裝完最小化-rhel-centos-7-後需要做的-30-件事情-四" aria-label="Permalink to “安裝完最小化 RHEL/CentOS 7 後需要做的 30 件事情（四）”">​</a></h1><h3 id="_17-安裝-webmin" tabindex="-1">17. 安裝 Webmin <a class="header-anchor" href="#_17-安裝-webmin" aria-label="Permalink to “17. 安裝 Webmin”">​</a></h3><p>Webmin 是基於 Web 的 Linux 配置工具。它像一箇中央系統，用於配置各種系統設置，比如用户、磁盤分配、服務以及 HTTP 服務器、Apache、MySQL 等的配置。</p><pre><code># wget http://prdownloads.sourceforge.net/webadmin/webmin-1.740-1.noarch.rpm
# rpm -ivh webmin-*.rpm
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Install-Webmin.jpeg" alt="在 CentOS 7 上安裝 Webmin"></p><p><em>安裝 Webmin</em></p>`,6)),r("p",null,[e[1]||(e[1]=t("安裝完 webmin 後，你會在終端上得到一個消息，提示你用 root 密碼在端口 10000 登錄你的主機 (",-1)),p(n,{href:"http://ip-address:10000"},{default:o(()=>[...e[0]||(e[0]=[t("http://ip-address:10000",-1)])]),_:1}),e[2]||(e[2]=t(")。 如果運行的是無接口的服務器你可以轉發端口然後從有接口的服務器上訪問它。（LCTT 譯註：無接口[headless]服務器指沒有訪問接口或界面的服務器，在此次場景，指的是是出於內網的服務器，可採用外網/路由器映射來訪問該端口）",-1))]),e[17]||(e[17]=i(`<h3 id="_18-啓用第三方庫" tabindex="-1">18. 啓用第三方庫 <a class="header-anchor" href="#_18-啓用第三方庫" aria-label="Permalink to “18. 啓用第三方庫”">​</a></h3><p>添加不受信任的庫並不是一個好主意，尤其是在生產環境中，這可能導致致命的問題。但僅作為例子在這裏我們會添加一些社區證實可信任的庫，以安裝第三方工具和軟件包。</p><p>為企業版 Linux（EPEL）庫添加額外的軟件包。</p><pre><code># yum install epel-release
</code></pre><p>添加社區企業版 Linux （Community Enterprise Linux）庫：</p><pre><code># rpm -Uvh http://www.elrepo.org/elrepo-release-7.0-2.el7.elrepo.noarch.rpm
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/install-epel-repo.jpeg" alt="安裝 Epel 庫"></p><p><em>安裝 Epel 庫</em></p><p><strong>注意！</strong> 添加第三方庫的時候尤其需要注意。</p><h3 id="_19-安裝-7-zip-工具" tabindex="-1">19. 安裝 7-zip 工具 <a class="header-anchor" href="#_19-安裝-7-zip-工具" aria-label="Permalink to “19. 安裝 7-zip 工具”">​</a></h3><p>在最小化安裝 CentOS 時你並沒有獲得類似 unzip 或者 untar 的工具。我們可以選擇根據需要來安裝每個工具，或一個能處理所有格式的工具。7-zip 就是一個能壓縮和解壓所有已知類型文件的工具。</p><pre><code># yum install p7zip
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Install-7zip-tool.jpeg" alt="安裝 7zip 工具"></p><p><em>安裝 7zip 工具</em></p><p><strong>注意</strong>: 該軟件包從 Fedora EPEL 7 的庫中下載和安裝。</p><h3 id="_20-安裝-ntfs-3g-驅動" tabindex="-1">20. 安裝 NTFS-3G 驅動 <a class="header-anchor" href="#_20-安裝-ntfs-3g-驅動" aria-label="Permalink to “20. 安裝 NTFS-3G 驅動”">​</a></h3><p>NTFS-3G，一個很小但非常有用的 NTFS 驅動，在大部分類 UNIX 發行版上都可用。它對於掛載和訪問 Windows NTFS 文件系統很有用。儘管也有其它可用的替代品，比如 Tuxera，但 NTFS-3G 是使用最廣泛的。</p><pre><code># yum install ntfs-3g
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Install-NTFS-3G.jpeg" alt="在 CentOS 上安裝 NTFS-3G"></p><p><em>安裝 NTFS-3G 用於掛載 Windows 分區</em></p><p>ntfs-3g 安裝完成之後，你可以使用以下命令掛載 Windows NTFS 分區（我的 Windows 分區是 /dev/sda5）。</p><pre><code># mount -ro ntfs-3g /dev/sda5 /mnt
# cd /mnt
# ls -l
</code></pre><h3 id="_21-安裝-vsftpd-ftp-服務器" tabindex="-1">21. 安裝 Vsftpd FTP 服務器 <a class="header-anchor" href="#_21-安裝-vsftpd-ftp-服務器" aria-label="Permalink to “21. 安裝 Vsftpd FTP 服務器”">​</a></h3><p>VSFTPD 表示 Very Secure File Transfer Protocol Daemon，是用於類 UNIX 系統的 FTP 服務器。它是現今最高效和安全的 FTP 服務器之一。</p><pre><code># yum install vsftpd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Install-FTP.jpeg" alt="在 CentOS 7 上安裝 Vsftpd"></p><p><em>安裝 Vsftpd FTP</em></p><p>編輯配置文件 ‘/etc/vsftpd/vsftpd.conf’ 用於保護 vsftpd。</p><pre><code># vi /etc/vsftpd/vsftpd.conf
</code></pre><p>編輯一些值並使其它行保留原樣，除非你知道自己在做什麼。</p><pre><code>anonymous_enable=NO
local_enable=YES
write_enable=YES
chroot_local_user=YES
</code></pre><p>你也可以更改端口號，記得讓 vsftpd 端口通過防火牆。</p><pre><code># firewall-cmd --add-port=21/tcp
# firewall-cmd --reload
</code></pre><p>下一步重啓 vsftpd 並啓用開機自動啓動。</p><pre><code># systemctl restart vsftpd
# systemctl enable vsftpd
</code></pre><h3 id="_22-安裝和配置-sudo" tabindex="-1">22. 安裝和配置 sudo <a class="header-anchor" href="#_22-安裝和配置-sudo" aria-label="Permalink to “22. 安裝和配置 sudo”">​</a></h3><p>sudo 通常被稱為 super do 或者 suitable user do，是一個類 UNIX 操作系統中用其它用户的安全權限執行程序的軟件。讓我們來看看怎樣配置 sudo。</p><pre><code># visudo
</code></pre><p>這會打開 /etc/sudoers 並進行編輯</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/sudoers-File.jpeg" alt="sudoers 文件"></p><p><em>sudoers 文件</em></p><ol><li><p>給一個已經創建好的用户（比如 tecmint）賦予所有權限（等同於 root）。</p><pre><code> tecmint   ALL=(ALL)    ALL
</code></pre></li><li><p>如果給一個已經創建好的用户（比如 tecmint）賦予除了重啓和關閉服務器以外的所有權限（等同於 root）。</p><p>首先，再一次打開文件並編輯如下內容：</p><pre><code> cmnd_Alias nopermit = /sbin/shutdown, /sbin/reboot
</code></pre><p>然後，用邏輯操作符（!）添加該別名。</p><pre><code> tecmint   ALL=(ALL)    ALL,!nopermit
</code></pre></li><li><p>如果准許一個組（比如 debian）運行一些 root 權限命令，比如（增加或刪除用户）。</p><pre><code> cmnd_Alias permit = /usr/sbin/useradd, /usr/sbin/userdel
</code></pre><p>然後，給組 debian 增加權限。</p><pre><code> debian ALL=(ALL) permit
</code></pre></li></ol><h3 id="_23-安裝並啓用-selinux" tabindex="-1">23. 安裝並啓用 SELinux <a class="header-anchor" href="#_23-安裝並啓用-selinux" aria-label="Permalink to “23. 安裝並啓用 SELinux”">​</a></h3><p>SELinux 表示 Security-Enhanced Linux，是內核級別的安全模組。</p><pre><code># yum install selinux-policy
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Install-SElinux.jpeg" alt="在 CentOS 7 上安裝 SElinux"></p><p><em>安裝 SElinux 策略</em></p><p>查看 SELinux 當前模式。</p><pre><code># getenforce
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Check-SELinux-Mode.jpeg" alt="查看 SELinux 模式"></p><p><em>查看 SELinux 模式</em></p><p>輸出是 Enforcing，意味着 SELinux 策略已經生效。</p><p>如果需要調試，可以臨時設置 selinux 模式為允許。不需要重啓。</p><pre><code># setenforce 0
</code></pre><p>調試完了之後再次設置 selinux 為強制模式，無需重啓。</p><pre><code># setenforce 1
</code></pre><p>（LCTT 譯註：在生產環境中，SELinux 固然會提升安全，但是也確實會給應用部署和運行帶來不少麻煩。具體是否部署，需要根據情況而定。）</p><h3 id="_24-安裝-rootkit-hunter" tabindex="-1">24. 安裝 Rootkit Hunter <a class="header-anchor" href="#_24-安裝-rootkit-hunter" aria-label="Permalink to “24. 安裝 Rootkit Hunter”">​</a></h3><p>Rootkit Hunter，簡寫為 RKhunter，是在 Linux 系統中掃描 rootkits 和其它可能有害攻擊的程序。</p><pre><code># yum install rkhunter
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Install-Rootkit-Hunter.jpeg" alt="安裝 Rootkit Hunter"></p><p><em>安裝 Rootkit Hunter</em></p><p>在 Linux 中，從腳本文件以計劃作業的形式運行 rkhunter 或者手動掃描有害攻擊。</p><pre><code># rkhunter --check
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Scan-for-rootkits.png" alt="掃描 rootkits"></p><p><em>掃描 rootkits</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/RootKit-Results.png" alt="RootKit 掃描結果"></p><p><em>RootKit 掃描結果</em></p><hr>`,69)),r("p",null,[e[4]||(e[4]=t("via: ",-1)),p(n,{href:"http://www.tecmint.com/things-to-do-after-minimal-rhel-centos-7-installation/4/"},{default:o(()=>[...e[3]||(e[3]=[t("http://www.tecmint.com/things-to-do-after-minimal-rhel-centos-7-installation/4/",-1)])]),_:1})]),r("p",null,[e[8]||(e[8]=t("作者：",-1)),p(n,{href:"http://www.tecmint.com/author/avishek/"},{default:o(()=>[...e[5]||(e[5]=[t("Avishek Kumar",-1)])]),_:1}),e[9]||(e[9]=t(" 譯者：",-1)),p(n,{href:"https://github.com/ictlyh"},{default:o(()=>[...e[6]||(e[6]=[t("ictlyh",-1)])]),_:1}),e[10]||(e[10]=t(" 校對：",-1)),p(n,{href:"https://github.com/wxy"},{default:o(()=>[...e[7]||(e[7]=[t("wxy",-1)])]),_:1})]),r("p",null,[e[13]||(e[13]=t("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[11]||(e[11]=[t("LCTT",-1)])]),_:1}),e[14]||(e[14]=t(" 原創翻譯，",-1)),p(n,{href:"http://linux.cn/"},{default:o(()=>[...e[12]||(e[12]=[t("Linux中國",-1)])]),_:1}),e[15]||(e[15]=t(" 榮譽推出",-1))])])}const b=a(m,[["render",c]]);export{g as __pageData,b as default};
